import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        address receiver = address(0x1234);
        uint amount = 0.5 ether;
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        bool ok;
        try c.sendTo{value: 0}(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        uint expectedRefBalance = (1 ether) - amount;
        assertEq(address(c).balance, expectedRefBalance);
    }
}

